1	// Turns a raw agent tool call into a line worth showing a non-developer.
2	//
3	// Every line here is derived from a tool call that ACTUALLY HAPPENED. There is
4	// deliberately no timed script of plausible-sounding steps: fake progress that
5	// finishes before the real build does is worse than no progress at all, and
6	// people spot it immediately — it is the tell that a product is a demo.
7	//
8	// The audience is someone who described a barber shop and is watching a screen.
9	// "Writing src/components/Hero.tsx" means nothing to them; "Writing the hero
10	// section" does. Where a path has no honest plain-English reading, we fall back
11	// to the filename rather than inventing a friendly label for it.
12	
13	/** Files whose purpose isn't guessable from the name. */
14	const KNOWN_PATHS: Record<string, string> = {
15	  "index.html": "the page title and link preview",
16	  "src/App.tsx": "the page layout",
17	  "src/index.css": "the styles",
18	  "src/main.tsx": "the app entry point",
19	  "package.json": "the project config",
20	  "vite.config.ts": "the build config",
21	  "tsconfig.json": "the TypeScript config",
22	};
23	
24	/** "FeatureGrid" -> "feature grid", "FAQ" -> "FAQ", "CTASection" -> "CTA section" */
25	function humanizeComponentName(name: string): string {
26	  const words = name
27	    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
28	    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
29	    .split(/[\s_-]+/)
30	    .filter(Boolean);
31	
32	  // Lowercase per word, not across the whole string: an all-caps word is an
33	  // initialism (FAQ, CTA, SEO) and "cta section" reads like a typo.
34	  return words
35	    .map((w) => (/^[A-Z0-9]{2,}$/.test(w) ? w : w.toLowerCase()))
36	    .join(" ");
37	}
38	
39	/** A human description of a project file, e.g. "the pricing section". */
40	export function describePath(path: string): string {
41	  const clean = path.replace(/^\.?\//, "");
42	  if (KNOWN_PATHS[clean]) return KNOWN_PATHS[clean];
43	
44	  const match = clean.match(/^src\/components\/(?:ui\/)?(.+)\.(tsx|jsx|ts|js)$/);
45	  if (match) {
46	    const label = humanizeComponentName(match[1].split("/").pop() ?? match[1]);
47	    // "ui/Button" is a primitive, not a page section — calling it a "section"
48	    // would be a lie the user could see through in the preview.
49	    const noun = clean.includes("/ui/") ? "component" : "section";
50	    // Don't append a noun the name already ends with: "CTASection" must read
51	    // "the CTA section", never "the CTA section section".
52	    if (new RegExp(`\\b${noun}$`, "i").test(label)) return `the ${label}`;
53	    return `the ${label} ${noun}`;
54	  }
55	
56	  if (clean.endsWith(".css")) return "the styles";
57	  return clean;
58	}
59	
60	type ToolInput = Record<string, unknown>;
61	
62	function pathFrom(input: ToolInput): string | null {
63	  const raw = input.file_path ?? input.path ?? input.filePath;
64	  if (typeof raw !== "string" || !raw) return null;
65	
66	  const normalized = raw.replace(/\\/g, "/");
67	
68	  // Already project-relative — the API engine passes these straight through,
69	  // and stripping them to a bare filename loses the src/components/ prefix
70	  // that describePath needs to recognise a section at all.
71	  const isAbsolute = normalized.startsWith("/") || /^[A-Za-z]:\//.test(normalized);
72	  if (!isAbsolute) return normalized.replace(/^\.\//, "");
73	
74	  // The SDK works in a temp checkout and reports absolute paths; everything
75	  // downstream — and the user — only cares about the project-relative part.
76	  const srcIndex = normalized.lastIndexOf("/src/");
77	  if (srcIndex !== -1) return normalized.slice(srcIndex + 1);
78	  const parts = normalized.split("/");
79	  return parts[parts.length - 1] || null;
80	}
81	
82	/**
83	 * A progress line for one tool call, or null when the call isn't worth
84	 * narrating. Returning null is the common case for inspection tools — a line
85	 * per Grep would bury the lines that matter.
86	 */
87	export function narrateTool(toolName: string, input: ToolInput): string | null {
88	  const path = pathFrom(input);
89	
90	  switch (toolName) {
91	    case "Write":
92	    case "write_file":
93	      return path ? `Writing ${describePath(path)}` : "Writing a file";
94	
95	    case "Edit":
96	      return path ? `Updating ${describePath(path)}` : "Making an edit";
97	
98	    case "delete_file":
99	      return path ? `Removing ${describePath(path)}` : "Removing a file";
100	
101	    case "Read":
102	    case "Glob":
103	    case "Grep":
104	      // Collapsed to one recurring line on purpose. The route dedupes
105	      // consecutive identical lines, so a run of twelve Reads shows once.
106	      return "Looking through the project";
107	
108	    case "Bash":
109	      return "Running a command";
110	
111	    default:
112	      return null;
113	  }
114	}
