55	function escapeHtml(s: string): string {
56	  return s
57	    .replace(/&/g, "&amp;")
58	    .replace(/</g, "&lt;")
59	    .replace(/>/g, "&gt;")
60	    .replace(/"/g, "&quot;");
61	}
