67	/**
68	 * Undo the entity encoding in text pulled back OUT of the HTML.
69	 *
70	 * The title is read from inside <title>…</title>, where it is already encoded —
71	 * a site called "Bloom & Co" is stored as "Bloom &amp; Co". Composing the
72	 * fallback description from that string and then escaping it again produced
73	 * "Bloom &amp;amp; Co", and the literal entity showed up in every link preview.
74	 * Decoding first, then escaping once, is the round trip that holds.
75	 *
76	 * Only the five entities escapeHtml/escapeXml can produce. A general HTML
77	 * entity decoder is not wanted here: this exists purely to invert our own
78	 * escaping, and anything else the builder wrote should pass through untouched.
79	 */
80	function decodeHtml(s: string): string {
81	  return s
82	    .replace(/&lt;/g, "<")
83	    .replace(/&gt;/g, ">")
84	    .replace(/&quot;/g, '"')
85	    .replace(/&apos;/g, "'")
86	    // Ampersand LAST, so "&amp;lt;" decodes to "&lt;" rather than "<".
87	    .replace(/&amp;/g, "&");
88	}
