90	/** Absolutise a root-relative URL against the site's public base. */
91	function absolutise(value: string, base: string): string {
92	  if (/^https?:\/\//i.test(value) || value.startsWith("data:")) return value;
93	  return `${base.replace(/\/$/, "")}/${value.replace(/^\//, "")}`;
