99	 * is left exactly as-is, since it had the site's actual content in view and
100	 * this function does not.
101	 */
102	export function applySeo(html: string, opts: { projectName: string; baseUrl: string }): string {
103	  const { projectName, baseUrl } = opts;
104	  if (!/<head[\s>]/i.test(html)) return html; // not a full document; leave alone
105	
106	  let out = html;
107	
108	  // 1. Title — replace the placeholder, or add one if missing entirely.
109	  const titleMatch = out.match(/<title>([\s\S]*?)<\/title>/i);
110	  const currentTitle = titleMatch?.[1]?.trim();
111	  const title = !currentTitle || currentTitle === PLACEHOLDER_TITLE ? projectName : currentTitle;
112	  if (titleMatch) {
113	    if (currentTitle !== title) {
114	      out = out.replace(/<title>[\s\S]*?<\/title>/i, `<title>${escapeHtml(title)}</title>`);
115	    }
116	  } else {
117	    out = out.replace(/<head([^>]*)>/i, `<head$1>\n    <title>${escapeHtml(title)}</title>`);
118	  }
119	
120	  const inject: string[] = [];
121	
122	  // Upsert a <meta>/<link>: fill it when the tag is absent OR present with an
123	  // empty value. The foundation ships empty `content=""` scaffolding to show
124	  // the builder what to write, so "tag exists" alone is not good enough — an
125	  // existence-only check would leave those empty forever.
126	  const upsert = (attrRe: RegExp, valueAttr: "content" | "href", value: string, tag: string) => {
127	    const existing = out.match(attrRe);
128	    if (!existing) {
129	      inject.push(tag);
130	      return;
131	    }
132	    const valRe = new RegExp(`${valueAttr}=["']([^"']*)["']`, "i");
133	    const current = existing[0].match(valRe)?.[1];
134	    if (current === undefined || current.trim() === "") {
135	      out = out.replace(existing[0], tag);
136	    }
137	  };
138	
139	  // decodeHtml first: `title` may have come straight out of <title>…</title>,
140	  // where it is already escaped. Without this, escapeHtml below double-encodes
141	  // it and the raw entity is what people see in the link preview.
142	  const desc = `${decodeHtml(title)} — built with Kodely.`;
143	  upsert(
144	    /<meta\s+name=["']description["'][^>]*>/i,
145	    "content",
146	    desc,
147	    `<meta name="description" content="${escapeHtml(desc)}" />`,
148	  );
149	  upsert(
150	    /<link\s+rel=["']canonical["'][^>]*>/i,
151	    "href",
152	    baseUrl,
153	    `<link rel="canonical" href="${escapeHtml(baseUrl)}" />`,
154	  );
155	  upsert(
156	    /<meta\s+property=["']og:title["'][^>]*>/i,
157	    "content",
158	    title,
159	    `<meta property="og:title" content="${escapeHtml(title)}" />`,
160	  );
161	  upsert(
162	    /<meta\s+property=["']og:description["'][^>]*>/i,
163	    "content",
164	    desc,
165	    `<meta property="og:description" content="${escapeHtml(desc)}" />`,
166	  );
167	  upsert(
168	    /<meta\s+property=["']og:type["'][^>]*>/i,
169	    "content",
170	    "website",
171	    `<meta property="og:type" content="website" />`,
172	  );
173	  upsert(
174	    /<meta\s+property=["']og:url["'][^>]*>/i,
175	    "content",
176	    baseUrl,
177	    `<meta property="og:url" content="${escapeHtml(baseUrl)}" />`,
178	  );
179	  upsert(
180	    /<meta\s+name=["']twitter:card["'][^>]*>/i,
181	    "content",
182	    "summary_large_image",
183	    `<meta name="twitter:card" content="summary_large_image" />`,
184	  );
185	
186	  if (inject.length) {
187	    out = out.replace(/<\/head>/i, `  ${inject.join("\n    ")}\n  </head>`);
188	  }
189	
190	  // Crawlers reject relative og:image, so absolutise whatever the builder set.
191	  out = out.replace(
192	    /(<meta\s+property=["']og:image["']\s+content=["'])([^"']+)(["'])/gi,
193	    (_m, pre, url, post) => `${pre}${escapeHtml(absolutise(url, baseUrl))}${post}`,
194	  );
195	
196	  return out;
197	}
