204	/**
205	 * sitemap.xml from the site's published HTML files. Generated per request so
206	 * it can use the visitor-facing host and can never drift from what is served.
207	 */
208	export function sitemapXml(baseUrl: string, htmlPaths: string[], lastMod?: Date): string {
209	  const base = baseUrl.replace(/\/$/, "");
210	  const seen = new Set<string>();
211	  const urls = htmlPaths
212	    .map((p) => (p === "index.html" ? "" : `/${p.replace(/^\//, "")}`))
213	    .filter((u) => (seen.has(u) ? false : (seen.add(u), true)))
214	    .map((u) => {
215	      const loc = escapeXml(base + u);
216	      const mod = lastMod ? `\n    <lastmod>${lastMod.toISOString().slice(0, 10)}</lastmod>` : "";
