1	// A minimal ZIP writer over node:zlib. The only thing Kodely zips is a project's
2	// source tree — a few dozen small UTF-8 text files — which isn't enough to
3	// justify carrying a zip dependency through every install and deploy.
4	//
5	// Deliberately NOT ZIP64: this emits the classic format, which tops out at 4 GB
6	// per entry and 65,535 entries. Source trees are nowhere near either limit; if
7	// they ever get there, reach for a real library rather than extending this.
8	
9	import { deflateRaw } from "node:zlib";
10	
11	const LOCAL_FILE_HEADER = 0x04034b50;
12	const CENTRAL_FILE_HEADER = 0x02014b50;
13	const END_OF_CENTRAL_DIR = 0x06054b50;
14	
15	// Bit 11 tells the extractor that names are UTF-8 rather than the ancient
16	// IBM code page the format otherwise assumes.
17	const FLAG_UTF8_NAMES = 0x0800;
18	
19	const METHOD_STORE = 0;
20	const METHOD_DEFLATE = 8;
21	
22	// High byte 3 = Unix, so the external attributes below are read as file mode.
23	const VERSION_MADE_BY = (3 << 8) | 20;
24	const VERSION_NEEDED = 20;
25	
26	// Regular file, rw-r--r--. Without this, extractors on Unix hand the user a
27	// tree of mode-000 files. The `>>> 0` matters: the shift alone overflows into
28	// a negative signed int32, which writeUInt32LE rejects outright.
29	const UNIX_FILE_MODE = (0o100644 << 16) >>> 0;
30	
31	const CRC_TABLE = (() => {
32	  const table = new Uint32Array(256);
33	  for (let i = 0; i < 256; i++) {
34	    let c = i;
35	    for (let bit = 0; bit < 8; bit++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
36	    table[i] = c >>> 0;
37	  }
38	  return table;
39	})();
40	
41	function crc32(data: Uint8Array): number {
42	  let c = 0xffffffff;
43	  for (let i = 0; i < data.length; i++) c = CRC_TABLE[(c ^ data[i]) & 0xff] ^ (c >>> 8);
44	  return (c ^ 0xffffffff) >>> 0;
45	}
46	
47	// ZIP stores timestamps as DOS date/time: two-second resolution, no timezone,
48	// and nothing before 1980 is representable.
49	function dosDateTime(when: Date): { time: number; date: number } {
50	  const year = Math.max(when.getUTCFullYear(), 1980);
51	  return {
52	    time: (when.getUTCHours() << 11) | (when.getUTCMinutes() << 5) | (when.getUTCSeconds() >> 1),
53	    date: ((year - 1980) << 9) | ((when.getUTCMonth() + 1) << 5) | when.getUTCDate(),
54	  };
55	}
56	
57	// Entry names decide where an extractor writes on the user's disk, and these
58	// paths are whatever the agent happened to write into the database. Drop any
59	// segment that could climb out of the extraction directory (zip-slip) before
60	// it ships.
61	function safeEntryName(path: string): string {
62	  return path
63	    .replace(/\\/g, "/")
64	    .split("/")
65	    .filter((segment) => segment !== "" && segment !== "." && segment !== "..")
66	    .join("/");
67	}
68	
69	function deflate(data: Buffer): Promise<Buffer> {
70	  return new Promise((resolve, reject) => {
71	    deflateRaw(data, { level: 9 }, (err, result) => (err ? reject(err) : resolve(result)));
72	  });
73	}
74	
75	export type ZipEntry = {
76	  path: string;
77	  content: string;
78	  modifiedAt?: Date;
79	};
80	
81	async function* zipChunks(entries: ZipEntry[]): AsyncGenerator<Buffer> {
82	  // Central directory records are only ~46 bytes + name each, so holding them
83	  // all until the end costs almost nothing — unlike the file bodies, which are
84	  // yielded and dropped as we go.
85	  const centralDirectory: Buffer[] = [];
86	  let offset = 0;
87	  let count = 0;
88	
89	  for (const entry of entries) {
90	    const name = Buffer.from(safeEntryName(entry.path), "utf8");
91	    if (name.length === 0) continue;
92	
93	    const body = Buffer.from(entry.content, "utf8");
94	    const compressed = await deflate(body);
95	    // Deflate grows already-dense or tiny inputs; falling back to STORE keeps
96	    // an entry from ever being bigger zipped than raw.
97	    const useStore = compressed.length >= body.length;
98	    const payload = useStore ? body : compressed;
99	    const method = useStore ? METHOD_STORE : METHOD_DEFLATE;
100	    const crc = crc32(body);
101	    const { time, date } = dosDateTime(entry.modifiedAt ?? new Date());
102	
103	    const local = Buffer.alloc(30);
104	    local.writeUInt32LE(LOCAL_FILE_HEADER, 0);
105	    local.writeUInt16LE(VERSION_NEEDED, 4);
106	    local.writeUInt16LE(FLAG_UTF8_NAMES, 6);
107	    local.writeUInt16LE(method, 8);
108	    local.writeUInt16LE(time, 10);
109	    local.writeUInt16LE(date, 12);
110	    local.writeUInt32LE(crc, 14);
111	    local.writeUInt32LE(payload.length, 18);
112	    local.writeUInt32LE(body.length, 22);
113	    local.writeUInt16LE(name.length, 26);
114	    local.writeUInt16LE(0, 28); // extra field length
115	
116	    yield local;
117	    yield name;
118	    yield payload;
119	
120	    const central = Buffer.alloc(46);
121	    central.writeUInt32LE(CENTRAL_FILE_HEADER, 0);
122	    central.writeUInt16LE(VERSION_MADE_BY, 4);
123	    central.writeUInt16LE(VERSION_NEEDED, 6);
124	    central.writeUInt16LE(FLAG_UTF8_NAMES, 8);
125	    central.writeUInt16LE(method, 10);
126	    central.writeUInt16LE(time, 12);
127	    central.writeUInt16LE(date, 14);
128	    central.writeUInt32LE(crc, 16);
129	    central.writeUInt32LE(payload.length, 20);
130	    central.writeUInt32LE(body.length, 24);
131	    central.writeUInt16LE(name.length, 28);
132	    central.writeUInt16LE(0, 30); // extra field length
133	    central.writeUInt16LE(0, 32); // file comment length
134	    central.writeUInt16LE(0, 34); // disk number start
135	    central.writeUInt16LE(0, 36); // internal attributes
136	    central.writeUInt32LE(UNIX_FILE_MODE, 38);
137	    central.writeUInt32LE(offset, 42);
138	    centralDirectory.push(central, name);
139	
140	    offset += local.length + name.length + payload.length;
141	    count++;
142	  }
143	
144	  const directoryOffset = offset;
145	  let directorySize = 0;
146	  for (const chunk of centralDirectory) {
147	    directorySize += chunk.length;
148	    yield chunk;
149	  }
150	
151	  const end = Buffer.alloc(22);
152	  end.writeUInt32LE(END_OF_CENTRAL_DIR, 0);
153	  end.writeUInt16LE(0, 4); // this disk number
154	  end.writeUInt16LE(0, 6); // disk holding the central directory
155	  end.writeUInt16LE(count, 8);
156	  end.writeUInt16LE(count, 10);
157	  end.writeUInt32LE(directorySize, 12);
158	  end.writeUInt32LE(directoryOffset, 16);
159	  end.writeUInt16LE(0, 20); // archive comment length
160	  yield end;
161	}
162	
163	// Streamed rather than buffered so a large project never has to exist twice in
164	// server memory (once as rows, once as a finished archive) just to be sent.
165	export function zipStream(entries: ZipEntry[]): ReadableStream<Uint8Array> {
166	  const chunks = zipChunks(entries);
167	  return new ReadableStream<Uint8Array>({
168	    async pull(controller) {
169	      const { done, value } = await chunks.next();
170	      if (done) controller.close();
171	      else controller.enqueue(value);
172	    },
173	    cancel() {
174	      // Client hung up mid-download — let the generator release its buffers
175	      // instead of leaving it parked on a yield.
176	      void chunks.return(undefined);
177	    },
178	  });
179	}
