190	//   • false — a Telegram bot, a Discord webhook, or an off-origin .php collector
191	//     has no legitimate role anywhere in a generated static marketing site, so
192	//     anywhere in the same file is damning enough.
193	//   • true  — formsubmit.co and mailto: are the NORMAL way a static site wires
194	//     up a contact form. A site with a contact form in the footer and a members
195	//     login on another page would otherwise be blocked outright, which is
196	//     exactly the kind of false positive that makes a gate like this
197	//     unshippable. These have to be wired to the password form itself.
198	const EXFIL_CHANNELS: { name: string; re: RegExp; nearPassword: boolean }[] = [
199	  { name: "Telegram bot API", re: /api\.telegram\.org\/bot/gi, nearPassword: false },
200	  { name: "Discord webhook", re: /discord(?:app)?\.com\/api\/webhooks/gi, nearPassword: false },
201	  {
202	    name: "off-origin PHP collector",
203	    re: /(?:action\s*[:=]\s*|fetch\s*\(\s*|axios\.post\s*\(\s*|sendBeacon\s*\(\s*)["'`](?:https?:)?\/\/[^"'`\s]+\.php\b/gi,
204	    nearPassword: false,
205	  },
206	  { name: "formsubmit.co relay", re: /\bformsubmit\.co\b/gi, nearPassword: true },
207	  { name: "mailto: form action", re: /action\s*[:=]\s*["'`]mailto:[^"'`]{1,120}/gi, nearPassword: true },
208	];
209	
210	// How far a "normally innocent" exfil channel may sit from a password field and
211	// still be read as the destination for it. One <form> of markup, roughly.
212	const SAME_FORM_RADIUS = 900;
213	
214	const OFF_ORIGIN_POST_RE =
215	  /(?:action\s*[:=]\s*|fetch\s*\(\s*|axios\.post\s*\(\s*|navigator\.sendBeacon\s*\(\s*)["'`](https?:\/\/[^"'`\s]{4,160})/gi;
216	
217	const SEED_PHRASE_RE =
218	  /\b(?:seed\s+phrase|recovery\s+phrase|secret\s+recovery\s+phrase|mnemonic(?:\s+phrase)?|(?:12|18|24)[-\s]word\s+(?:phrase|seed)|wallet\s+private\s+key|keystore\s+(?:file|json))\b/gi;
219	
220	// Security-education copy ("never share your seed phrase with anyone") reads
221	// almost identically to a drainer's own form label. If the surrounding text is
222	// a warning, the finding is downgraded rather than dropped — still recorded.
223	const SEED_WARNING_RE = /\b(?:never|do\s*n[o']t|no\s+one|nobody|don't)\b[^.!?]{0,90}\b(?:share|enter|reveal|type|give|ask|store)\b/i;
224	
225	const WALLET_CONNECT_RE =
226	  /window\.ethereum|eth_requestAccounts|@?walletconnect|window\.solana|window\.phantom|web3modal|BrowserProvider|Web3Provider|rainbowkit/gi;
227	
228	// Asset-DELEGATION primitives, not payment primitives. A legitimate "donate
229	// ETH" button uses eth_sendTransaction with a fixed value — that is deliberately
230	// NOT in this list, because flagging it would punish an honest crypto site. What
231	// a drainer needs, and an honest site does not, is permission to move assets it
232	// does not own: an unlimited allowance, setApprovalForAll, or an offline Permit
233	// signature.
234	// A note on why the raw 4-byte selectors are here as well as the method names:
235	// the method name often does NOT survive the build. A drainer that hand-rolls
236	// its calldata leaves only `"0xa22cb465…"` in the minified bundle — verified
237	// against real `vite build` output, where a `/* setApprovalForAll */` comment
238	// next to that selector was stripped and the name-based pattern went silent.
239	// An 8-hex-digit selector literal is an exact string with no plausible
240	// accidental collision, and it is still only one leg of the conjunction.
241	const DRAINER_PRIMITIVES: { name: string; re: RegExp }[] = [
242	  { name: "setApprovalForAll", re: /\bsetApprovalForAll\b|0xa22cb465/g },
243	  { name: "increaseAllowance", re: /\bincreaseAllowance\b|0x39509351/g },
244	  { name: "unlimited ERC-20 allowance", re: /[fF]{60,}|\bMaxUint256\b|\bMAX_UINT256\b|2\s*\*\*\s*256/g },
245	  { name: "off-chain Permit signature", re: /eth_signTypedData(?:_v[34])?|\bsignTypedData\b/g },
246	  { name: "delegated transferFrom", re: /\btransferFrom\s*\(|0x23b872dd|0x42842e0e|0xf242432a|0x2eb2c2d6/g },
247	];
248	
249	// eval-of-decoded-string. Minifiers produce dense code but never this shape;
250	// phishing kits and drainer templates ship it routinely to hide the drop URL.
251	const OBFUSCATED_PAYLOAD_RE =
252	  /\beval\s*\(\s*(?:atob|unescape|decodeURIComponent|String\.fromCharCode)|\bnew\s+Function\s*\(\s*(?:atob|unescape)|document\.write\s*\(\s*(?:unescape|atob)/gi;
253	
254	// ── Engine ────────────────────────────────────────────────────────────────
255	
256	const EVIDENCE_RADIUS = 60;
257	// Tuned against real `vite build` output, not guessed. Phishing copy names the
258	// brand INSIDE the solicitation ("Sign in to your Microsoft account", "Your
259	// PayPal account has been limited"), so the two land within a few dozen
260	// characters of each other once class attributes are stripped. A legitimate
261	// page that happens to contain both — a film blog with a member login in one
262	// section and "now streaming on Netflix" in another — keeps them hundreds of
263	// characters apart. 120 sits in that gap with room on both sides.
264	const BRAND_WINDOW_RADIUS = 120;
265	// Wider, because a label and its <input> can legitimately be separated by a
266	// wrapper element or two.
267	const INPUT_WINDOW_RADIUS = 220;
268	const MAX_FINDINGS_PER_RULE = 3;
269	
270	function snippet(content: string, index: number, length: number): string {
271	  const start = Math.max(0, index - EVIDENCE_RADIUS);
272	  const end = Math.min(content.length, index + length + EVIDENCE_RADIUS);
273	  const raw = content.slice(start, end).replace(/\s+/g, " ").trim();
274	  return (start > 0 ? "…" : "") + raw + (end < content.length ? "…" : "");
275	}
276	
277	function windowAround(content: string, index: number, length: number, radius: number): string {
278	  return content.slice(
279	    Math.max(0, index - radius),
280	    Math.min(content.length, index + length + radius),
281	  );
282	}
283	
284	function test(re: RegExp, text: string): boolean {
285	  re.lastIndex = 0;
286	  return re.test(text);
287	}
288	
289	function firstMatch(re: RegExp, text: string): RegExpExecArray | null {
290	  re.lastIndex = 0;
291	  return re.exec(text);
292	}
293	
294	function scannable(file: ModerationInput): string | null {
295	  const lower = file.path.toLowerCase();
296	  if (SKIP_EXTENSIONS.some((ext) => lower.endsWith(ext))) return null;
297	  // Same reasoning as lib/secret-scan.ts: an inlined image or font is bytes,
298	  // not content, and base64 will happily contain any substring you like.
299	  return file.content.replace(DATA_URI_RE, "").replace(CLASS_ATTR_RE, "");
300	}
301	
302	function runHeuristics(files: ModerationInput[]): ModerationFinding[] {
303	  const findings: ModerationFinding[] = [];
304	  const perRule = new Map<string, number>();
305	  const seen = new Set<string>();
306	
307	  const add = (f: ModerationFinding) => {
308	    const key = `${f.rule}�${f.path}�${f.evidence}`;
309	    if (seen.has(key)) return;
310	    const count = perRule.get(f.rule) ?? 0;
311	    if (count >= MAX_FINDINGS_PER_RULE) return;
312	    seen.add(key);
313	    perRule.set(f.rule, count + 1);
314	    findings.push(f);
315	  };
316	
317	  for (const file of files) {
318	    const content = scannable(file);
319	    if (content === null) continue;
320	
321	    // Every password field's offset, not just the first: the "is this exfil
322	    // channel wired to the password form?" test needs all of them.
323	    const passwordFields: RegExpExecArray[] = [];
324	    PASSWORD_INPUT_RE.lastIndex = 0;
325	    let pm: RegExpExecArray | null;
326	    while ((pm = PASSWORD_INPUT_RE.exec(content)) !== null) passwordFields.push(pm);
327	    const hasPasswordInput = passwordFields.length > 0;
328	    const nearAPasswordField = (index: number) =>
329	      passwordFields.some((p) => Math.abs(p.index - index) <= SAME_FORM_RADIUS);
330	    const hasWalletConnect = test(WALLET_CONNECT_RE, content);
331	
332	    // ── Rule: brand impersonation of a credential form ──────────────────
333	    // Three legs, all required, because each one alone is common and benign:
334	    //   1. the file actually collects a password (a link to a login page or an
335	    //      OAuth button does not),
336	    //   2. a third-party brand is named,
337	    //   3. within ~160 chars of that name, the page SOLICITS credentials in the
338	    //      second person.
339	    // Plus a negative check that the brand isn't merely being linked, credited,
340	    // or offered as an identity provider.
341	    if (hasPasswordInput) {
342	      for (const { brand, re } of IMPERSONATION_TARGETS) {
343	        re.lastIndex = 0;
344	        let m: RegExpExecArray | null;
345	        while ((m = re.exec(content)) !== null) {
346	          const before = content.slice(Math.max(0, m.index - 40), m.index);
347	          if (BENIGN_BRAND_CONTEXT_RE.test(before)) continue;
348	
349	          const around = windowAround(content, m.index, m[0].length, BRAND_WINDOW_RADIUS);
350	          if (test(CREDENTIAL_SOLICITATION_RE, around)) {
351	            add({
352	              rule: "brand-impersonation-credential-form",
353	              severity: "high",
354	              path: file.path,
355	              evidence: snippet(content, m.index, m[0].length),
356	              note: `A password field sits on a page that asks the visitor to sign in to / verify a ${brand} account. Publishing a login page branded as someone else's service is not allowed.`,
357	            });
358	          } else {
359	            // Recorded, never blocking: a third-party brand next to a login
360	            // form is usually an integration list, a partner logo, or an OAuth
361	            // provider. Worth having in the record if the site is reported.
362	            add({
363	              rule: "brand-mention-near-credential-form",
364	              severity: "low",
365	              path: file.path,
366	              evidence: snippet(content, m.index, m[0].length),
367	              note: `${brand} is named in a file that also contains a password field. Usually benign (integration, partner, or OAuth button) — recorded for context only.`,
368	            });
369	          }
370	        }
371	      }
372	    }
373	
374	    // ── Rule: credentials leaving via a known drop channel ───────────────
375	    if (hasPasswordInput) {
376	      for (const { name, re, nearPassword } of EXFIL_CHANNELS) {
377	        re.lastIndex = 0;
378	        let m: RegExpExecArray | null;
379	        while ((m = re.exec(content)) !== null) {
380	          // Not `continue`-on-first-miss: a site can use formsubmit.co twice,
381	          // once for a harmless contact form and once for the password form.
382	          if (nearPassword && !nearAPasswordField(m.index)) continue;
383	          add({
384	            rule: "credential-exfil-channel",
385	            severity: "high",
386	            path: file.path,
387	            evidence: snippet(content, m.index, m[0].length),
388	            note: `A password field is submitted to a ${name}. That is a credential drop site, not a form backend.`,
389	          });
390	          break;
391	        }
392	      }
393	
394	      // ── Rule: credentials POSTed off-origin ────────────────────────────
395	      // Medium, not high: a real product's login page legitimately posts to its
396	      // own API on another host. We can't tell that apart from a drop site
397	      // without knowing the site's intended origin, so this records rather than
398	      // blocks.
399	      OFF_ORIGIN_POST_RE.lastIndex = 0;
400	      let om: RegExpExecArray | null;
401	      while ((om = OFF_ORIGIN_POST_RE.exec(content)) !== null) {
402	        add({
403	          rule: "credential-post-off-origin",
404	          severity: "medium",
405	          path: file.path,
406	          evidence: snippet(content, om.index, om[0].length),
407	          note: `A file containing a password field submits to an off-origin URL (${om[1].slice(0, 80)}). Legitimate if that is your own backend.`,
408	        });
409	      }
410	
411	      // ── Rule: a password field at all ─────────────────────────────────
412	      // Informational. Published projects are static builds with no server, so
413	      // a password box here can never actually authenticate anyone — but mock
414	      // login UIs and design demos are a real, legitimate thing people build.
415	      add({
416	        rule: "password-form-on-static-site",
417	        severity: "low",
418	        path: file.path,
419	        evidence: snippet(content, passwordFields[0].index, passwordFields[0][0].length),
420	        note: "Password input on a statically hosted site (no backend). Recorded for context only.",
421	      });
422	    }
423	
424	    // ── Rule: seed-phrase / private-key capture ─────────────────────────
425	    // A wallet's recovery phrase has exactly one legitimate destination: the
426	    // wallet. Any web form asking for one is a drainer. The only real
427	    // ambiguity is educational copy warning people NOT to enter it, which is
428	    // why the warning check exists.
429	    SEED_PHRASE_RE.lastIndex = 0;
430	    let sm: RegExpExecArray | null;
431	    while ((sm = SEED_PHRASE_RE.exec(content)) !== null) {
432	      const around = windowAround(content, sm.index, sm[0].length, INPUT_WINDOW_RADIUS);
433	      if (!test(INPUT_ELEMENT_RE, around)) continue; // prose about seed phrases, no form
434	      const isWarning = SEED_WARNING_RE.test(around);
435	      add({
436	        rule: "wallet-seed-phrase-capture",
437	        severity: isWarning ? "low" : "high",
438	        path: file.path,
439	        evidence: snippet(content, sm.index, sm[0].length),
440	        note: isWarning
441	          ? "Seed-phrase wording near an input, but the surrounding copy reads as a warning not to share one. Recorded, not blocking."
442	          : "An input field asks for a wallet seed / recovery phrase or private key. No legitimate site collects these.",
443	      });
444	    }
445	
446	    // ── Rule: wallet-connect + asset-delegation primitive ───────────────
447	    if (hasWalletConnect) {
448	      let matchedPrimitive = false;
449	      for (const { name, re } of DRAINER_PRIMITIVES) {
450	        const m = firstMatch(re, content);
451	        if (!m) continue;
452	        matchedPrimitive = true;
453	        add({
454	          rule: "wallet-drainer-approval",
455	          severity: "high",
456	          path: file.path,
457	          evidence: snippet(content, m.index, m[0].length),
458	          note: `Page connects a wallet and then requests ${name} — permission to move assets it does not own. That is the shape of a drainer, not a payment.`,
459	        });
460	      }
461	      if (!matchedPrimitive) {
462	        const m = firstMatch(WALLET_CONNECT_RE, content);
463	        if (m) {
464	          add({
465	            rule: "wallet-connect-present",
466	            severity: "low",
467	            path: file.path,
468	            evidence: snippet(content, m.index, m[0].length),
469	            note: "Page connects a browser wallet. Unusual for a generated static site (the build foundation ships no web3 dependencies) but not abusive on its own.",
470	          });
471	        }
472	      }
473	    }
474	
475	    // ── Rule: runtime-decoded executable payload ────────────────────────
476	    {
477	      const m = firstMatch(OBFUSCATED_PAYLOAD_RE, content);
478	      if (m) {
479	        add({
480	          rule: "runtime-obfuscated-payload",
481	          severity: "medium",
482	          path: file.path,
483	          evidence: snippet(content, m.index, m[0].length),
484	          note: "Code decodes a string and executes it at runtime. Minifiers do not emit this shape; it is normally used to hide a destination URL.",
485	        });
486	      }
487	    }
488	  }
489	
490	  return findings;
491	}
492	
493	/**
494	 * The current analyzer: pattern conjunctions over file text. Cheap, synchronous
495	 * in practice, and honest about its ceiling (see the header comment).
496	 */
497	export const heuristicProvider: ModerationProvider = {
498	  name: "heuristics-v1",
499	  analyze: async (files) => runHeuristics(files),
500	};
501	
502	let activeProvider: ModerationProvider = heuristicProvider;
503	
504	/**
505	 * Swap in a different analyzer — a model call, a vendor API, a shadow-mode
506	 * ensemble. Callers of moderateForPublish() do not change. Intended for tests
507	 * and for the eventual real classifier; there is no runtime config for it yet.
508	 */
509	export function setModerationProvider(provider: ModerationProvider): void {
510	  activeProvider = provider;
511	}
512	
513	/**
514	 * Analyzes the files about to become publicly reachable and returns what it
515	 * found. Returns findings, NOT a verdict — the caller applies policy (today:
516	 * app/api/projects/[id]/publish/route.ts refuses on `high`, records the rest).
517	 *
518	 * Async on purpose even though the current provider is pure CPU: a real
519	 * classifier will be a network call, and this signature is the seam.

