async function collect(stream) {
  const chunks = [];
  const reader = stream.getReader();
  for (;;) { const { done, value } = await reader.read(); if (done) break; chunks.push(Buffer.from(value)); }
  return Buffer.concat(chunks);
}
const big = "hello world ".repeat(500);
const buf = await collect(zipStream([
  { path: "a.txt", content: "hi", modifiedAt: new Date("2026-01-02T03:04:06Z") },
  { path: "b.txt", content: big, modifiedAt: new Date("2026-01-02T03:04:06Z") },
  { path: "../../evil.txt", content: "x", modifiedAt: new Date("2026-01-02T03:04:06Z") },
  { path: "..", content: "x" },
]));
console.log("total bytes", buf.length);
// walk local headers
let off = 0; const entries = [];
while (buf.readUInt32LE(off) === 0x04034b50) {
  const method = buf.readUInt16LE(off + 8);
  const crc = buf.readUInt32LE(off + 14);
  const comp = buf.readUInt32LE(off + 18);
  const uncomp = buf.readUInt32LE(off + 22);
  const nlen = buf.readUInt16LE(off + 26);
  const elen = buf.readUInt16LE(off + 28);
  const name = buf.subarray(off + 30, off + 30 + nlen).toString("utf8");
  const payload = buf.subarray(off + 30 + nlen + elen, off + 30 + nlen + elen + comp);
  entries.push({ name, method, crc: crc.toString(16), comp, uncomp, body: method === 0 ? payload.toString("utf8") : inflateRawSync(payload).toString("utf8") });
  off += 30 + nlen + elen + comp;
}
console.log(entries.map((e) => ({ ...e, body: e.body.slice(0, 20) })));
const eocdOff = buf.length - 22;
console.log("eocd sig", buf.readUInt32LE(eocdOff).toString(16), "count", buf.readUInt16LE(eocdOff + 8), "dirSize", buf.readUInt32LE(eocdOff + 12), "dirOff", buf.readUInt32LE(eocdOff + 16));
// dos time
const dosTime = buf.readUInt16LE(10), dosDate = buf.readUInt16LE(12);
console.log("dostime", dosTime.toString(2), "date", dosDate.toString(2), "year", ((dosDate >> 9) & 0x7f) + 1980, "mon", (dosDate >> 5) & 0xf, "day", dosDate & 0x1f, "h", (dosTime >> 11) & 0x1f, "m", (dosTime >> 5) & 0x3f, "s2", dosTime & 0x1f);
