test("narrateTool: an absolute path with no src/ falls back to the filename", () => {
  assert.equal(narrateTool("Write", { file_path: "/tmp/checkout/package.json" }), "Writing the project config");
});

test("narrateTool: the deepest src/ wins for a nested checkout", () => {
  assert.equal(
    narrateTool("Write", { file_path: "/srv/src/apps/build/src/components/Hero.tsx" }),
    "Writing the hero section",
  );
});

test("narrateTool: file_path, path and filePath are all accepted", () => {
  for (const key of ["file_path", "path", "filePath"]) {
    assert.equal(narrateTool("Write", { [key]: "src/components/Hero.tsx" }), "Writing the hero section");
  }
});

// ── narrateTool: the tool vocabulary ───────────────────────────────────────

test("narrateTool: write / edit / delete each have their own verb", () => {
  const p = { file_path: "src/components/Hero.tsx" };
  assert.equal(narrateTool("Write", p), "Writing the hero section");
  assert.equal(narrateTool("write_file", p), "Writing the hero section");
  assert.equal(narrateTool("Edit", p), "Updating the hero section");
  assert.equal(narrateTool("delete_file", p), "Removing the hero section");
});

test("narrateTool: inspection tools collapse to one recurring line", () => {
  for (const tool of ["Read", "Glob", "Grep"]) {
    assert.equal(narrateTool(tool, { file_path: "src/components/Hero.tsx" }), "Looking through the project");
  }
  assert.equal(narrateTool("Bash", { command: "npm run build" }), "Running a command");
});

test("narrateTool: an unknown tool is not narrated at all", () => {
  // Returning null is the point — a line per unrecognised call would bury the
  // lines that matter.
  assert.equal(narrateTool("Task", {}), null);
  assert.equal(narrateTool("WebFetch", { url: "https://example.com" }), null);
  assert.equal(narrateTool("", {}), null);
});

test("narrateTool: a file tool with no usable path still says something honest", () => {
  assert.equal(narrateTool("Write", {}), "Writing a file");
  assert.equal(narrateTool("Edit", { file_path: "" }), "Making an edit");
  assert.equal(narrateTool("delete_file", { file_path: 42 }), "Removing a file");
});

test("narrateTool: never leaks a raw component filename to the user", () => {
  const line = narrateTool("Write", { file_path: "/tmp/x/src/components/TestimonialCarousel.tsx" });
  assert.ok(!line.includes(".tsx"), `narration leaked a filename: ${line}`);
  assert.ok(!line.includes("/"), `narration leaked a path: ${line}`);
});

// lib/feedback-intent.ts — coarse buckets for what someone types after a build.
//
// The cost of a single wrong answer is one miscounted row, so these tests are
// about the SHAPE of the rules (plural tolerance, precedence, praise never
// outranking real work), not about pinning every phrase in English.

import test from "node:test";
import assert from "node:assert/strict";

import { INTENTS, classifyFollowUp } from "../lib/feedback-intent.ts";

// ── The plural regression ──────────────────────────────────────────────────

test('"colors" is visual — the \\b after colou?r used to fail on the plural', () => {
  // THE REGRESSION. `\bcolou?r\b` does not match "colors": the trailing word
  // boundary fails against the s, which silently mis-bucketed the single most
  // common visual request in the product.
  assert.equal(classifyFollowUp("make the colors warmer"), "visual");
  assert.equal(classifyFollowUp("the colors are too dark"), "visual");
});

test("both spellings, both numbers, all land on visual", () => {
  for (const word of ["color", "colors", "colour", "colours"]) {
    assert.equal(classifyFollowUp(`change the ${word}`), "visual", word);
  }
});

test("other plural-tolerant visual nouns match in both numbers", () => {
  for (const [singular, plural] of [
    ["font", "fonts"],
    ["background", "backgrounds"],
    ["gradient", "gradients"],
    ["shadow", "shadows"],
    ["margin", "margins"],
    ["theme", "themes"],
  ]) {
    assert.equal(classifyFollowUp(`the ${singular} needs work`), "visual", singular);
    assert.equal(classifyFollowUp(`the ${plural} need work`), "visual", plural);
  }
});

// ── Praise must never outrank real work ────────────────────────────────────

test('"great, now make the colors warmer" is visual, not praise', () => {
  // A change request that opens politely is still a change request.
  assert.equal(classifyFollowUp("great, now make the colors warmer"), "visual");
});

test("a polite opener never swallows the request that follows it", () => {
  assert.equal(classifyFollowUp("perfect, now add a contact form"), "add");
  assert.equal(classifyFollowUp("love it! remove the pricing table"), "remove");
  assert.equal(classifyFollowUp("nice — move the hero above the features"), "layout");
  assert.equal(classifyFollowUp("thanks, but it's blank on mobile"), "broken");
});

test("bare praise is still praise", () => {
  for (const s of ["wow", "this is amazing", "looks great", "thank you", "perfect", "beautiful"]) {
    assert.equal(classifyFollowUp(s), "praise", s);
  }
});

// ── Precedence: broken outranks everything ─────────────────────────────────

test('"broken" wins even when the sentence is phrased as a styling note', () => {
  assert.equal(classifyFollowUp("the colors are broken"), "broken");
  assert.equal(classifyFollowUp("the layout doesn't work"), "broken");
  assert.equal(classifyFollowUp("nice site but the page is blank"), "broken");
});

test("the broken bucket catches the ways people actually report a dead page", () => {
  for (const s of [
    "it's broken",
    "not working",
    "doesn't work",
    "the page is blank",
    "just a white screen",
    "empty page",
    "I get an error",
    "it crashed",
    "there are bugs",
    "nothing loads",
    "won't load",
    "the build failed",
  ]) {
    assert.equal(classifyFollowUp(s), "broken", s);
  }
});

// ── The remaining buckets ──────────────────────────────────────────────────

test("remove outranks add, so a mixed sentence is not counted as growth", () => {
  assert.equal(classifyFollowUp("remove the FAQ"), "remove");
  assert.equal(classifyFollowUp("delete the pricing table and add a gallery"), "remove");
  assert.equal(classifyFollowUp("get rid of the video"), "remove");
  assert.equal(classifyFollowUp("I don't want the testimonials"), "remove");
});

test("add", () => {
  for (const s of ["add a pricing section", "can you add a map", "include opening hours", "create a blog page"]) {
    assert.equal(classifyFollowUp(s), "add", s);
  }
});

test("layout", () => {
  for (const s of ["move the hero up", "swap the sections", "make the logo bigger", "centre the heading", "use two columns"]) {
    assert.equal(classifyFollowUp(s), "layout", s);
  }
});

test("content", () => {
  for (const s of ["fix the spelling", "update the phone number", "the headline is wrong", "change the prices"]) {
    assert.equal(classifyFollowUp(s), "content", s);
  }
});

// ── "other" is a real answer ───────────────────────────────────────────────

test("nothing recognisable is 'other', not a guess", () => {
  // An "other" rate that climbs is the signal that the rules have drifted, so
  // it must not be quietly absorbed into a neighbouring bucket.
  assert.equal(classifyFollowUp("asdfghjkl"), "other");
  assert.equal(classifyFollowUp("hmm"), "other");
});

test("empty and whitespace-only prompts are 'other'", () => {
  assert.equal(classifyFollowUp(""), "other");
  assert.equal(classifyFollowUp("   "), "other");
  assert.equal(classifyFollowUp("\n\t "), "other");
});

// ── Invariants ─────────────────────────────────────────────────────────────

test("classifyFollowUp is case-insensitive", () => {
  assert.equal(classifyFollowUp("MAKE THE COLORS WARMER"), "visual");
  assert.equal(classifyFollowUp("Remove The Footer"), "remove");
});

test("classifyFollowUp always returns a declared intent, and is deterministic", () => {
  const samples = [
    "",
    "great, now make the colors warmer",
    "it's blank",
    "add a gallery",
    "remove the footer",
    "move the hero",
    "fix the phone number",
    "wow",
    "qqqq",
  ];
  for (const s of samples) {
    const first = classifyFollowUp(s);
    assert.ok(INTENTS.includes(first), `${JSON.stringify(s)} -> ${first}`);
    // Regexes carry lastIndex state when they are /g; these must not.
    assert.equal(classifyFollowUp(s), first, `${JSON.stringify(s)} is not stable across calls`);
    assert.equal(classifyFollowUp(s), first);
  }
});

test("leading and trailing whitespace does not change the answer", () => {
  assert.equal(classifyFollowUp("  add a gallery  "), classifyFollowUp("add a gallery"));
});

// lib/site-seo.ts — the serve-time SEO backstop for published sites.
//
// Note what is NOT here: the og:title entity round trip. It is still broken,
// so its test lives in tests/open-bugs.test.mjs with the evidence.

import test from "node:test";
import assert from "node:assert/strict";

import { applySeo, robotsTxt, siteBaseUrl, sitemapXml } from "../lib/site-seo.ts";

const doc = (head, body = "<p>hello</p>") =>
  `<!doctype html><html lang="en"><head>${head}</head><body>${body}</body></html>`;

const req = (host) => new Request("http://internal.invalid/", { headers: { host } });

/** The value of one attribute on the first tag matching `re`. */
function attr(html, re, name) {
  const tag = html.match(re);
  if (!tag) return null;
  return tag[0].match(new RegExp(`${name}=["']([^"']*)["']`, "i"))?.[1] ?? null;
}

const ogTitle = (html) => attr(html, /<meta\s+property=["']og:title["'][^>]*>/i, "content");
const ogUrl = (html) => attr(html, /<meta\s+property=["']og:url["'][^>]*>/i, "content");
const ogImage = (html) => attr(html, /<meta\s+property=["']og:image["'][^>]*>/i, "content");
const description = (html) => attr(html, /<meta\s+name=["']description["'][^>]*>/i, "content");
const canonical = (html) => attr(html, /<link\s+rel=["']canonical["'][^>]*>/i, "href");
const title = (html) => html.match(/<title>([\s\S]*?)<\/title>/i)?.[1] ?? null;

// ── siteBaseUrl ────────────────────────────────────────────────────────────

test("siteBaseUrl: a branded subdomain lives at the host root", () => {
  assert.equal(siteBaseUrl(req("bloom.kodely.site"), "bloom"), "https://bloom.kodely.site");
});

test("siteBaseUrl: anything else is served under /api/site/<slug>", () => {
  assert.equal(siteBaseUrl(req("staging.kodely.me"), "bloom"), "https://staging.kodely.me/api/site/bloom");
});

test("siteBaseUrl: only loopback is http — never trust x-forwarded-proto", () => {
  // Cloudflare terminates TLS at the edge and talks to the origin over plain
  // HTTP, so a forwarded proto of "http" is a lie for every real visitor. This
  // emitted http:// og:url on https-only sites, and Automatic HTTPS Rewrites
  // repaired the canonical but not the OG tag, so only the OG tag stayed wrong.
  const forwarded = new Request("http://internal.invalid/", {
    headers: { host: "bloom.kodely.site", "x-forwarded-proto": "http" },
  });
  assert.ok(siteBaseUrl(forwarded, "bloom").startsWith("https://"));

  for (const local of ["localhost:3000", "127.0.0.1:3000", "localhost"]) {
    assert.ok(siteBaseUrl(req(local), "bloom").startsWith("http://"), local);
  }
});

test("siteBaseUrl: the port is kept, because that is where the visitor is", () => {
  assert.equal(siteBaseUrl(req("localhost:3000"), "b"), "http://localhost:3000/api/site/b");
});

test("siteBaseUrl: a lookalike suffix is not treated as a branded subdomain", () => {
  // "notkodely.site" ends with "kodely.site" but not with ".kodely.site".
  assert.equal(siteBaseUrl(req("notkodely.site"), "b"), "https://notkodely.site/api/site/b");
});

// ── applySeo: leave the builder's work alone ───────────────────────────────

test("applySeo: a fragment with no <head> is returned untouched", () => {
  const fragment = "<div><h1>hi</h1></div>";
  assert.equal(applySeo(fragment, { projectName: "P", baseUrl: "https://p.kodely.site" }), fragment);
});

test("applySeo: a real title the builder wrote is preserved", () => {
  const html = doc("<title>Bloom Pilates — Reformer studio in Denver</title>");
  const out = applySeo(html, { projectName: "Bloom Pilates", baseUrl: "https://b.kodely.site" });
  assert.equal(title(out), "Bloom Pilates — Reformer studio in Denver");
});

test("applySeo: tags the builder already filled in are not overwritten", () => {
  const html = doc(
    `<title>Real Title</title>` +
      `<meta name="description" content="A description with real content in it." />` +
      `<meta property="og:title" content="Custom OG" />`,
  );
  const out = applySeo(html, { projectName: "P", baseUrl: "https://p.kodely.site" });
  assert.equal(description(out), "A description with real content in it.");
  assert.equal(ogTitle(out), "Custom OG");
});

// ── applySeo: fill the gaps ────────────────────────────────────────────────

test("applySeo: the foundation placeholder is replaced by the project name", () => {
  // Every site shipped as "Kodely Site" before this existed — in the browser
  // tab, in Google, and in every link preview.
  const out = applySeo(doc("<title>Kodely Site</title>"), {
    projectName: "Bloom Pilates",
    baseUrl: "https://b.kodely.site",
  });
  assert.equal(title(out), "Bloom Pilates");
  assert.ok(!out.includes("Kodely Site"));
});

test("applySeo: a missing <title> is injected", () => {
  const out = applySeo(doc('<meta charset="utf-8" />'), {
    projectName: "Bloom Pilates",
    baseUrl: "https://b.kodely.site",
  });
  assert.equal(title(out), "Bloom Pilates");
});

test("applySeo: an empty <title> counts as missing", () => {
  const out = applySeo(doc("<title>   </title>"), { projectName: "Bloom", baseUrl: "https://b.kodely.site" });
  assert.equal(title(out), "Bloom");
});

test("applySeo: scaffolding with an empty content= is filled, not left forever", () => {
  // The foundation ships empty content="" to show the builder what to write,
  // so an existence-only check would leave those blank on every published site.
  const out = applySeo(
    doc(`<title>Bloom</title><meta name="description" content="" /><meta property="og:url" content="" />`),
    { projectName: "Bloom", baseUrl: "https://b.kodely.site" },
  );
  assert.equal(description(out), "Bloom — built with Kodely.");
  assert.equal(ogUrl(out), "https://b.kodely.site");
});

test("applySeo: the full tag set is present after one pass", () => {
  const out = applySeo(doc("<title>Bloom</title>"), { projectName: "Bloom", baseUrl: "https://b.kodely.site" });
  assert.equal(description(out), "Bloom — built with Kodely.");
  assert.equal(canonical(out), "https://b.kodely.site");
  assert.equal(ogUrl(out), "https://b.kodely.site");
  assert.match(out, /<meta property="og:type" content="website" \/>/);
  assert.match(out, /<meta name="twitter:card" content="summary_large_image" \/>/);
  // Injected inside the head, not after it.
  assert.ok(out.indexOf('rel="canonical"') < out.indexOf("</head>"));
});

// ── applySeo: escaping and the entity round trip ───────────────────────────

test("applySeo: the fallback description does not double-escape an encoded title", () => {
  // THE REGRESSION. The title is read back out of <title>…</title>, where it
  // is ALREADY encoded — "Bloom & Co" is stored as "Bloom &amp; Co". Composing
  // the description from that and escaping again produced "Bloom &amp;amp; Co"
  // and the literal entity showed up in every link preview.
  const out = applySeo(doc("<title>Bloom &amp; Co</title>"), {
    projectName: "Ignored",
    baseUrl: "https://b.kodely.site",
  });
  assert.equal(description(out), "Bloom &amp; Co — built with Kodely.");
  assert.ok(!description(out).includes("&amp;amp;"), "the description double-escaped the ampersand");
});

test("applySeo: a raw project name IS escaped exactly once", () => {
  // The other direction: projectName has not been through HTML, so it needs
  // one pass of escaping and no decode.
  const out = applySeo(doc("<title>Kodely Site</title>"), {
    projectName: "Bloom & Co",
    baseUrl: "https://b.kodely.site",
  });
  assert.equal(title(out), "Bloom &amp; Co");
  assert.equal(description(out), "Bloom &amp; Co — built with Kodely.");
  assert.ok(!out.includes("&amp;amp;"));
});

test("applySeo: applying twice changes nothing", () => {
  // It rewrites on READ, so the same document goes through it on every single
  // request. A non-idempotent pass would compound with every page view.
  for (const head of [
    "<title>Bloom &amp; Co</title>",
    "<title>Kodely Site</title>",
    '<meta charset="utf-8" />',
    `<title>Bloom</title><meta name="description" content="" />`,
    `<title>Bloom</title><meta property="og:image" content="/hero.png" />`,
  ]) {
    const opts = { projectName: "Bloom & Co", baseUrl: "https://b.kodely.site" };
    const once = applySeo(doc(head), opts);
    assert.equal(applySeo(once, opts), once, `not idempotent for head: ${head}`);
  }
});

test("applySeo: a relative og:image is absolutised, an absolute one is left alone", () => {
  const opts = { projectName: "Bloom", baseUrl: "https://b.kodely.site" };
  assert.equal(
    ogImage(applySeo(doc(`<title>B</title><meta property="og:image" content="/hero.png" />`), opts)),
    "https://b.kodely.site/hero.png",
  );
  assert.equal(
    ogImage(applySeo(doc(`<title>B</title><meta property="og:image" content="hero.png" />`), opts)),
    "https://b.kodely.site/hero.png",
  );
  assert.equal(
    ogImage(applySeo(doc(`<title>B</title><meta property="og:image" content="https://cdn.example/x.png" />`), opts)),
    "https://cdn.example/x.png",
  );
  assert.equal(
    ogImage(applySeo(doc(`<title>B</title><meta property="og:image" content="data:image/png;base64,AA" />`), opts)),
    "data:image/png;base64,AA",
  );
});

test("applySeo: absolutising never doubles the slash", () => {
  const out = applySeo(doc(`<title>B</title><meta property="og:image" content="/hero.png" />`), {
    projectName: "B",
    baseUrl: "https://b.kodely.site/",
