// lib/assets/index.ts — the asset library's query function.
//
// findAssets is shaped like a tool call, so these tests treat it like one: the
// question is always "would a model asking this question get the right thing
// back", not "does the scorer return the number it returns today".

import test from "node:test";
import assert from "node:assert/strict";

import {
  ASSET_KINDS,
  assetCatalogSummary,
  findAssets,
  getAsset,
  listAssetIds,
  listAssets,
} from "../lib/assets/index.ts";

const ids = (matches) => matches.map((m) => m.id);

// ── The demonym regression ─────────────────────────────────────────────────

test('"french flag" returns France, not French Guiana', () => {
  // THE REGRESSION. Flag keywords are derived from the country NAME, so
  // "French Guiana" owned the literal token "french" and scored a full keyword
  // hit while France could only be reached through a discounted synonym. The
  // search returned three obscure territories and not the country anyone meant.
  assert.equal(findAssets("french flag", { limit: 1 })[0].id, "flag:fr");
});

test('"british flag" returns the United Kingdom, not a territory', () => {
  assert.equal(findAssets("british flag", { limit: 1 })[0].id, "flag:gb");
});

test("a sovereign country outscores or ties every territory named after it", () => {
  // The fix is entry-side: listing the demonym as a keyword on the country
  // lets it match the same token at the same strength as the territory.
  for (const [query, sovereign] of [
    ["french flag", "flag:fr"],
    ["british flag", "flag:gb"],
    ["american flag", "flag:us"],
  ]) {
    const top = findAssets(query, { kind: "flag", limit: 5 });
    const own = top.find((m) => m.id === sovereign);
    assert.ok(own, `${query} did not return ${sovereign} at all`);
    assert.equal(own.score, Math.max(...top.map((m) => m.score)), `${query}: ${sovereign} was outscored`);
  }
});

test("a territory search still finds the territory", () => {
  // The second token is the one only the territory carries.
  assert.equal(findAssets("french guiana", { limit: 1 })[0].id, "flag:gf");
});

test("other demonyms resolve to their country", () => {
  for (const [query, expected] of [
    ["german flag", "flag:de"],
    ["spanish flag", "flag:es"],
    ["irish flag", "flag:ie"],
    ["canadian flag", "flag:ca"],
    ["japanese flag", "flag:jp"],
    ["italian flag", "flag:it"],
  ]) {
    assert.equal(findAssets(query, { limit: 1 })[0].id, expected, query);
  }
});

test("a country name and its ISO code both find it", () => {
  assert.equal(findAssets("france", { kind: "flag", limit: 1 })[0].id, "flag:fr");
  assert.equal(findAssets("united states", { kind: "flag", limit: 1 })[0].id, "flag:us");
  assert.equal(findAssets("usa", { kind: "flag", limit: 1 })[0].id, "flag:us");
});

// ── Scoring shape ──────────────────────────────────────────────────────────

test("an exact id beats a keyword match", () => {
  const results = findAssets("wrench", { kind: "icon", limit: 5 });
  assert.equal(results[0].id, "icon:wrench");
  assert.ok(results[0].score > (results[1]?.score ?? 0));
});

test("a synonym hit never outranks the word the caller actually typed", () => {
  // "plumber" reaches the wrench only through SYNONYMS, so its score must be
  // strictly below what typing "wrench" scores.
  const literal = findAssets("wrench", { kind: "icon", limit: 1 })[0];
  const viaSynonym = findAssets("plumber", { kind: "icon", limit: 1 })[0];
  assert.equal(viaSynonym.id, "icon:wrench");
  assert.ok(viaSynonym.score < literal.score);
});

test("business vocabulary reaches a sensible icon", () => {
  for (const [query, expected] of [
    ["plumber", "icon:wrench"],
    ["electrician", "icon:zap"],
    ["barber", "icon:scissors"],
    ["dentist", "icon:tooth"],
    ["photographer", "icon:camera"],
  ]) {
    assert.equal(findAssets(query, { kind: "icon", limit: 1 })[0]?.id, expected, query);
  }
});

test("results are sorted by descending score", () => {
  const scores = findAssets("coffee", { limit: 20 }).map((m) => m.score);
  for (let i = 1; i < scores.length; i++) assert.ok(scores[i] <= scores[i - 1]);
});

test("ties break deterministically by id, so the same query never reshuffles", () => {
  const once = ids(findAssets("flag", { limit: 30 }));
  assert.deepEqual(ids(findAssets("flag", { limit: 30 })), once);
  assert.deepEqual(ids(findAssets("flag", { limit: 30 })), once);
});

test("a query that matches nothing returns nothing, rather than guessing", () => {
  assert.deepEqual(findAssets("zzzzqqqq"), []);
  assert.deepEqual(findAssets("xylophone quantum bagpipe"), []);
});

test("stopwords do not turn a real query into an empty one", () => {
  assert.equal(findAssets("a phone icon", { kind: "icon", limit: 1 })[0].id, "icon:phone");
  assert.equal(findAssets("the icons", { limit: 3 }).length, 3, "an all-stopword query lists the catalogue");
});

// ── Options ────────────────────────────────────────────────────────────────

test("limit is clamped to 1..100", () => {
  assert.equal(findAssets("flag", { limit: 1000 }).length, 100);
  assert.equal(findAssets("flag", { limit: 0 }).length, 1);
  assert.equal(findAssets("flag", { limit: -3 }).length, 1);
  assert.ok(findAssets("flag").length <= 20, "the default limit is 20");
});

test("kind filters the pool", () => {
  for (const kind of ASSET_KINDS) {
    const results = findAssets("", { kind, limit: 100 });
    assert.ok(results.every((m) => m.kind === kind), `kind=${kind} leaked another kind`);
  }
  const two = findAssets("", { kind: ["icon", "flag"], limit: 100 });
  assert.ok(two.every((m) => m.kind === "icon" || m.kind === "flag"));
});

test("an unrecognised kind is ignored rather than returning nothing", () => {
  // Better a slightly wide answer than an empty one from a typo in a tool call.
  assert.ok(findAssets("coffee", { kind: "nonsense", limit: 3 }).length > 0);
  assert.ok(findAssets("coffee", { kind: [], limit: 3 }).length > 0);
});

test("an empty query lists the catalogue instead of erroring", () => {
  const listed = findAssets("", { limit: 5 });
  assert.equal(listed.length, 5);
  assert.ok(listed.every((m) => m.score === 0), "listed items are not scored");
});

test("the icon weight option reaches the emitted source", () => {
  const regular = findAssets("phone", { kind: "icon", limit: 1 })[0].source;
  const bold = findAssets("phone", { kind: "icon", limit: 1, weight: "bold" })[0].source;
  assert.notEqual(regular, bold, "weight had no effect on the emitted markup");
});

// ── Every match must be paste-ready and CSP-safe ───────────────────────────

test("every match carries a non-empty source, usage and format", () => {
  for (const kind of ASSET_KINDS) {
    for (const m of listAssets(kind)) {
      assert.ok(m.source.length > 0, `${m.id} has an empty source`);
      assert.ok(m.usage.length > 0, `${m.id} has no usage line`);
      assert.ok(["jsx", "svg", "css", "text"].includes(m.format), `${m.id} has format ${m.format}`);
      assert.equal(m.kind, kind);
    }
  }
});

test("no source reaches out to a remote host — the sandbox CSP would drop it", () => {
  // Generated sites run under default-src 'self'; img-src 'self' data:. A
  // hosted asset would fail silently at serve time.
  for (const m of listAssets()) {
    assert.ok(
      !/\b(?:src|href)\s*=\s*["']https?:/i.test(m.source),
      `${m.id} references a remote host: ${m.source.slice(0, 120)}`,
    );
  }
});

test("jsx sources use JSX attribute spelling, not HTML", () => {
  for (const m of listAssets()) {
    if (m.format !== "jsx") continue;
    assert.ok(!/\sstroke-width=/.test(m.source), `${m.id} emits HTML-style stroke-width`);
    assert.ok(!/\sstroke-linecap=/.test(m.source), `${m.id} emits HTML-style stroke-linecap`);
    assert.ok(!/\sclass=/.test(m.source), `${m.id} emits class= instead of className=`);
  }
});

// ── Catalogue plumbing ─────────────────────────────────────────────────────

test("ids are unique and namespaced by kind", () => {
  const all = listAssetIds();
  assert.equal(new Set(all).size, all.length, "duplicate asset id");
  for (const id of all) assert.ok(ASSET_KINDS.includes(id.slice(0, id.indexOf(":"))), id);
});

test("getAsset round-trips every id in the catalogue", () => {
  for (const id of listAssetIds()) assert.equal(getAsset(id)?.id, id);
});

test("getAsset trims, and returns null rather than throwing on a bad id", () => {
  assert.equal(getAsset("  icon:phone  ")?.id, "icon:phone");
  assert.equal(getAsset("icon:does-not-exist"), null);
  assert.equal(getAsset(""), null);
  assert.equal(getAsset("constructor"), null);
  assert.equal(getAsset("__proto__"), null);
});

test("the catalogue summary agrees with the catalogue", () => {
  const summary = assetCatalogSummary();
  assert.equal(summary.total, listAssetIds().length);
  assert.equal(
    summary.byKind.reduce((n, k) => n + k.count, 0),
    summary.total,
  );
  for (const { kind, count } of summary.byKind) assert.equal(listAssetIds(kind).length, count);
  assert.equal(summary.flags.withSvg + summary.flags.emojiOnly, summary.flags.total);
});

// lib/flags.ts — only the parts reachable without a database.
//
// isEnabled, listFlags, setFlag, seedFlags and deleteOrphanFlag all read or
// write the FeatureFlag table and are deliberately NOT tested here (see
// scripts/test/README.md). What is testable is the part with no I/O and the
// most subtle failure mode: the bucketing function, whose bugs are invisible
// in production because every wrong answer still looks like a plausible one.

import test from "node:test";
import assert from "node:assert/strict";

import {
  FLAGS,
  FLAG_CACHE_TTL_MS,
  FLAG_KEYS,
  FLAG_SPECS,
  clampRolloutPct,
  invalidateFlagCache,
  rolloutBucket,
} from "../lib/flags.ts";

const SUBJECTS = Array.from({ length: 2000 }, (_, i) => `user-${i}`);

// ── rolloutBucket: stability ───────────────────────────────────────────────

test("rolloutBucket is stable for the same subject and key", () => {
  // Math.random() here would make a 50% UI rollout flicker between page loads
  // and split one user's builds across both engines.
  for (const id of ["alice", "cm3x9qk0000abcdefghij", ""]) {
    const first = rolloutBucket(id, FLAGS.sdkEngine);
    for (let i = 0; i < 25; i++) assert.equal(rolloutBucket(id, FLAGS.sdkEngine), first);
  }
});

test("rolloutBucket always lands in 0..99, as an integer", () => {
  for (const id of SUBJECTS) {
    const bucket = rolloutBucket(id, FLAGS.sdkEngine);
    assert.ok(Number.isInteger(bucket), `${id} -> ${bucket}`);
    assert.ok(bucket >= 0 && bucket < 100, `${id} -> ${bucket}`);
  }
});

test("rolloutBucket is a pure function of subject and key", () => {
  // No cached state, no clock, no process identity: a restart or a second
  // instance must produce the same answer or the rollout is not a rollout.
  assert.equal(rolloutBucket("alice", FLAGS.sdkEngine), rolloutBucket("alice", FLAGS.sdkEngine));
  invalidateFlagCache();
  assert.equal(rolloutBucket("alice", FLAGS.sdkEngine), rolloutBucket("alice", FLAGS.sdkEngine));
});

// ── rolloutBucket: uniformity ──────────────────────────────────────────────

test("rolloutBucket spreads sequential cuid-like ids across the range", () => {
  // The failure this pins: id.length % 100 or a charCodeAt sum puts ids
  // created near each other in the same bucket, so a 10% rollout selects one
  // contiguous afternoon of signups rather than a random tenth.
  const sequential = Array.from({ length: 500 }, (_, i) => `cm3x9qk00${String(i).padStart(4, "0")}zzzz`);
  const buckets = new Set(sequential.map((id) => rolloutBucket(id, FLAGS.sdkEngine)));
  assert.ok(buckets.size > 80, `500 near-identical ids only reached ${buckets.size} of 100 buckets`);
});

test("a 10% rollout selects roughly a tenth of subjects", () => {
  const selected = SUBJECTS.filter((id) => rolloutBucket(id, FLAGS.sdkEngine) < 10).length;
  const share = selected / SUBJECTS.length;
  assert.ok(share > 0.07 && share < 0.13, `10% rollout selected ${(share * 100).toFixed(1)}%`);
});

test("every bucket gets used, and none of them hogs the population", () => {
  const counts = new Array(100).fill(0);
  for (const id of SUBJECTS) counts[rolloutBucket(id, FLAGS.sdkEngine)]++;
  assert.equal(
    counts.reduce((a, b) => a + b, 0),
    SUBJECTS.length,
  );
  assert.ok(Math.min(...counts) > 0, "a bucket was never selected");
  // Expected 20 per bucket at n=2000; a hash that avalanches properly stays
  // well inside this. A truncating or biased hash does not.
  assert.ok(Math.max(...counts) < 60, `one bucket took ${Math.max(...counts)} of 2000`);
});

// ── rolloutBucket: decorrelation ───────────────────────────────────────────

test("mixing the key in decorrelates flags", () => {
  // Hash the user id alone and every flag at 50% picks the SAME half of the
  // user base: the unluckiest users get every experiment at once, and two
  // independent 50% rollouts are silently one cohort.
  const agree = SUBJECTS.filter(
    (id) => rolloutBucket(id, FLAGS.sdkEngine) < 50 === rolloutBucket(id, FLAGS.promptEnhance) < 50,
  ).length;
  const rate = agree / SUBJECTS.length;
  assert.ok(rate > 0.44 && rate < 0.56, `two 50% rollouts agreed on ${(rate * 100).toFixed(1)}% of subjects`);
});

test("the same subject gets a different bucket per flag", () => {
  const perFlag = FLAG_KEYS.map((key) => rolloutBucket("alice", key));
  assert.ok(new Set(perFlag).size > 1, "one subject landed in the same bucket for every flag");
});

test("neighbouring keys do not produce neighbouring buckets", () => {
  const a = rolloutBucket("alice", "feature.a");
  const b = rolloutBucket("alice", "feature.b");
  assert.notEqual(a, b);
});

// ── clampRolloutPct ────────────────────────────────────────────────────────

test("clampRolloutPct clamps to 0..100 and rounds to an integer", () => {
  assert.equal(clampRolloutPct(-5), 0);
  assert.equal(clampRolloutPct(0), 0);
  assert.equal(clampRolloutPct(50), 50);
  assert.equal(clampRolloutPct(100), 100);
  assert.equal(clampRolloutPct(105), 100);
  assert.equal(clampRolloutPct(33.4), 33);
  assert.equal(clampRolloutPct(33.6), 34);
});

test("clampRolloutPct treats a non-finite value as fully rolled out", () => {
  // A garbled form field must not silently shed traffic from a shipped feature.
  assert.equal(clampRolloutPct(NaN), 100);
  assert.equal(clampRolloutPct(Infinity), 100);
  assert.equal(clampRolloutPct(-Infinity), 100);
});

// ── The declared vocabulary ────────────────────────────────────────────────

test("every flag key has a spec, and every spec has a key", () => {
  assert.deepEqual(FLAG_KEYS.slice().sort(), Object.keys(FLAG_SPECS).sort());
  assert.equal(FLAG_KEYS.length, Object.values(FLAGS).length);
});

test("flag keys are unique", () => {
  assert.equal(new Set(FLAG_KEYS).size, FLAG_KEYS.length);
});

test("every flag reads as a capability that is ON — no inverted flags", () => {
  // Rule 2 of the module: there must be no flag whose enabled=true means "the
  // thing is broken/off", because that is how someone turns generation OFF at
  // 3am while trying to turn it off.
  for (const key of FLAG_KEYS) {
    assert.ok(
      /\.(enabled)$|^feature\./.test(key),
      `${key} does not read as a capability that is on when true`,
    );
    assert.ok(!/disabled|_off|\.off$|kill/.test(key), `${key} reads as an inverted flag`);
  }
});

test("every kill switch fails closed", () => {
  // The entire value of a kill switch is that "off" is enforceable. A kill
  // switch that failed open would stop working during exactly the incident it
  // exists for.
  for (const [key, spec] of Object.entries(FLAG_SPECS)) {
    if (spec.kind !== "kill") continue;
    assert.equal(spec.whenUnavailable, false, `${key} fails open`);
    assert.equal(spec.whenUnset, true, `${key} is off in a fresh environment`);
  }
});

test("every spec declares a reason for its fail direction", () => {
  for (const [key, spec] of Object.entries(FLAG_SPECS)) {
    assert.ok(["kill", "gate"].includes(spec.kind), key);
    assert.equal(typeof spec.whenUnset, "boolean", key);
    assert.equal(typeof spec.whenUnavailable, "boolean", key);
    assert.ok(spec.description.length > 10, `${key} has no usable description`);
    assert.ok(spec.reason.length > 40, `${key} does not explain its fail direction`);
  }
});

test("the cache TTL is short enough that a kill feels immediate", () => {
  // At a minute people click the button twice and then look for a deploy
  // button, which is the failure mode this module exists to remove.
  assert.ok(FLAG_CACHE_TTL_MS > 0 && FLAG_CACHE_TTL_MS <= 15_000);
});

test("invalidateFlagCache is safe to call with no cache and no database", () => {
  assert.doesNotThrow(() => {
    invalidateFlagCache();
    invalidateFlagCache();
  });
});

// lib/zip.ts — the hand-rolled ZIP writer behind "download my source".
//
// zipStream is the only export, so everything is asserted through the BYTES it
// produces. That is the right level anyway: a CRC or a length field that is
// wrong by one is invisible in any unit test of an internal helper and very
// visible in Windows Explorer.
//
// The archives are parsed back here with node:zlib rather than shelled out to
// an external unzip, so the suite stays hermetic.

import test from "node:test";
import assert from "node:assert/strict";
import { inflateRawSync, deflateRawSync } from "node:zlib";

import { zipStream } from "../lib/zip.ts";

const LOCAL = 0x04034b50;
const CENTRAL = 0x02014b50;
const EOCD = 0x06054b50;
const STORE = 0;
const DEFLATE = 8;

const FIXED_DATE = new Date("2026-01-02T03:04:06Z");

async function toBuffer(entries) {
  const reader = zipStream(entries).getReader();
  const chunks = [];
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(Buffer.from(value));
  }
  return Buffer.concat(chunks);
}

/** Parse the local file headers, decompressing each payload. */
function readLocalEntries(buf) {
  const out = [];
  let offset = 0;
  while (offset + 30 <= buf.length && buf.readUInt32LE(offset) === LOCAL) {
    const method = buf.readUInt16LE(offset + 8);
    const nameLength = buf.readUInt16LE(offset + 26);
    const extraLength = buf.readUInt16LE(offset + 28);
    const compressedSize = buf.readUInt32LE(offset + 18);
    const bodyStart = offset + 30 + nameLength + extraLength;
    const payload = buf.subarray(bodyStart, bodyStart + compressedSize);
    out.push({
      offset,
      versionNeeded: buf.readUInt16LE(offset + 4),
      flags: buf.readUInt16LE(offset + 6),
      method,
      dosTime: buf.readUInt16LE(offset + 10),
      dosDate: buf.readUInt16LE(offset + 12),
      crc: buf.readUInt32LE(offset + 14),
      compressedSize,
      uncompressedSize: buf.readUInt32LE(offset + 22),
      name: buf.subarray(offset + 30, offset + 30 + nameLength).toString("utf8"),
      content: (method === STORE ? payload : inflateRawSync(payload)).toString("utf8"),
    });
    offset = bodyStart + compressedSize;
  }
  return out;
}

function readEocd(buf) {
  const at = buf.length - 22;
  assert.equal(buf.readUInt32LE(at), EOCD, "no end-of-central-directory record at the tail");
  return {
    at,
    entriesOnDisk: buf.readUInt16LE(at + 8),
    entriesTotal: buf.readUInt16LE(at + 10),
    directorySize: buf.readUInt32LE(at + 12),
    directoryOffset: buf.readUInt32LE(at + 16),
    commentLength: buf.readUInt16LE(at + 20),
  };
}

/** Parse the central directory the EOCD points at. */
function readCentralDirectory(buf) {
  const { directoryOffset, entriesTotal } = readEocd(buf);
  const out = [];
  let offset = directoryOffset;
  for (let i = 0; i < entriesTotal; i++) {
    assert.equal(buf.readUInt32LE(offset), CENTRAL, `central record ${i} has the wrong signature`);
    const nameLength = buf.readUInt16LE(offset + 28);
    out.push({
      versionMadeBy: buf.readUInt16LE(offset + 4),
      flags: buf.readUInt16LE(offset + 8),
      method: buf.readUInt16LE(offset + 10),
      crc: buf.readUInt32LE(offset + 16),
      compressedSize: buf.readUInt32LE(offset + 20),
      uncompressedSize: buf.readUInt32LE(offset + 24),
      externalAttributes: buf.readUInt32LE(offset + 38),
      localHeaderOffset: buf.readUInt32LE(offset + 42),
      name: buf.subarray(offset + 46, offset + 46 + nameLength).toString("utf8"),
    });
    offset += 46 + nameLength + buf.readUInt16LE(offset + 30) + buf.readUInt16LE(offset + 32);
  }
  return out;
}

// ── CRC ────────────────────────────────────────────────────────────────────

test("crc32 matches the standard vector for 'hello world'", () => {
  // 0x0D4A1185 is the published CRC-32 of "hello world". A table built with a
  // wrong polynomial, or a missing final xor, produces a different number that
  // still looks like a plausible checksum — and an archive every extractor
  // rejects as corrupt.
  return toBuffer([{ path: "h.txt", content: "hello world", modifiedAt: FIXED_DATE }]).then((buf) => {
    assert.equal(readLocalEntries(buf)[0].crc, 0x0d4a1185);
  });
});

test("crc32 of the empty string is 0", async () => {
  // An entry with no content still gets a header, and 0 is the correct CRC.
  const buf = await toBuffer([{ path: "e.txt", content: "", modifiedAt: FIXED_DATE }]);
  const [entry] = readLocalEntries(buf);
  assert.equal(entry.crc, 0);
  assert.equal(entry.uncompressedSize, 0);
});

test("crc32 is computed over the UTF-8 bytes, not the JS string", async () => {
  // "naïve ☕" is 7 code points but 11 bytes. A CRC over char codes would
  // disagree with every extractor on the planet.
  const content = "naïve ☕";
  const buf = await toBuffer([{ path: "u.txt", content, modifiedAt: FIXED_DATE }]);
  const [entry] = readLocalEntries(buf);
  assert.equal(entry.uncompressedSize, Buffer.byteLength(content, "utf8"));
  assert.notEqual(entry.uncompressedSize, content.length);
  assert.equal(entry.content, content);
});

test("the local and central CRCs agree for every entry", async () => {
  const buf = await toBuffer([
    { path: "a.txt", content: "short", modifiedAt: FIXED_DATE },
    { path: "b.txt", content: "hello world ".repeat(500), modifiedAt: FIXED_DATE },
    { path: "c.txt", content: "", modifiedAt: FIXED_DATE },
  ]);
  const local = readLocalEntries(buf);
  const central = readCentralDirectory(buf);
  assert.equal(local.length, central.length);
  for (let i = 0; i < local.length; i++) {
    assert.equal(central[i].crc, local[i].crc, `entry ${i}`);
    assert.equal(central[i].name, local[i].name);
    assert.equal(central[i].compressedSize, local[i].compressedSize);
    assert.equal(central[i].uncompressedSize, local[i].uncompressedSize);
    assert.equal(central[i].method, local[i].method);
  }
});

// ── STORE vs deflate ───────────────────────────────────────────────────────

test("a tiny entry falls back to STORE rather than growing", async () => {
  // Deflate adds framing to already-dense or tiny inputs. An entry must never
  // be bigger zipped than raw.
  const buf = await toBuffer([{ path: "a.txt", content: "hi", modifiedAt: FIXED_DATE }]);
  const [entry] = readLocalEntries(buf);
  assert.equal(entry.method, STORE);
  assert.equal(entry.compressedSize, 2);
  assert.equal(entry.uncompressedSize, 2);
  assert.equal(entry.content, "hi");
});

test("a compressible entry actually deflates", async () => {
  const content = "hello world ".repeat(500);
  const buf = await toBuffer([{ path: "b.txt", content, modifiedAt: FIXED_DATE }]);
  const [entry] = readLocalEntries(buf);
  assert.equal(entry.method, DEFLATE);
  assert.ok(entry.compressedSize < entry.uncompressedSize / 10);
  assert.equal(entry.content, content);
});

test("no entry is ever stored larger than its raw bytes", async () => {
  const samples = [
    "",
    "a",
    "hi",
    "{}",
    JSON.stringify({ name: "kodely", version: "0.1.0" }),
