test("the EOCD counts and sizes describe the archive that was actually written", async () => {
  const entries = [
    { path: "a.txt", content: "hi", modifiedAt: FIXED_DATE },
    { path: "b.txt", content: "hello world ".repeat(500), modifiedAt: FIXED_DATE },
